body:
New project works, and I'm definitely running the right sdk now. 

Still getting the same error.
```
E 0:00:01:210   VariantUtils.generic.cs:19 @ Godot.NativeInterop.godot_variant Godot.NativeInterop.VariantUtils+GenericConversion`1.ToVariant(T&): System.InvalidOperationException: The type is not supported for conversion to/from Variant: 'Godot.Variant[]'
  <C# Error>    System.InvalidOperationException
  <C# Source>   C:/Users/WarappaLocal/source/godot/modules/mono/glue/GodotSharp/GodotSharp/Core/NativeInterop/VariantUtils.generic.cs:19 @ Godot.NativeInterop.godot_variant Godot.NativeInterop.VariantUtils+GenericConversion`1.ToVariant(T&)
  <Stack Trace> VariantUtils.generic.cs:19 @ Godot.NativeInterop.godot_variant Godot.NativeInterop.VariantUtils+GenericConversion`1.ToVariant(T&)
                VariantUtils.generic.cs:196 @ Godot.NativeInterop.godot_variant Godot.NativeInterop.VariantUtils.CreateFrom<T>(T&)
                Variant.cs:161 @ Godot.Variant Godot.Variant.From<T>(T&)
                VariantError.cs:10 @ void VariantError._PhysicsProcess(double)
                VariantError_ScriptMethods.generated.cs:46 @ Godot.NativeInterop.godot_variant VariantError+ScriptMethodDispatchHelper+<>c.<CreateScriptMethod__PhysicsProcess1>b__0_0(Godot.GodotObject, Godot.NativeInterop.NativeVariantPtrArgs&)
                CSharpInstanceBridge.cs:49 @ bool Godot.Bridge.CSharpInstanceBridge.Invoke(Godot.GodotObject, Godot.NativeInterop.godot_string_name*&, Godot.NativeInterop.godot_variant**&, int, Godot.NativeInterop.godot_variant_call_error*&, Godot.NativeInterop.godot_variant&)
```
I managed to track the issue to an AnimationTree calling `emit_signal(animation_started)` - it appears that this method is getting invoked with one argument instead of two, hence a string is trying to be casted to Variant[]?

In this case, I am directly manipulating AnimationTree nodes at runtime through stringnames.

Here is the offending code, with the line that causes it commented
```csharp
public partial class Character3DAnimTree : AnimationTree {

    [Flags]
    public enum LimbName {
        None,
        LeftArm       = 1 << 0,
        RightArm      = 1 << 1,
        LeftLeg       = 1 << 2,
        RightLeg      = 1 << 3,
        Spine         = 1 << 4,
        Arms          = LeftArm  | RightArm,
        RightArmSpine = RightArm | Spine,
        Legs          = LeftLeg  | RightLeg,
        Left          = LeftArm  | LeftLeg,
        Right         = RightArm | RightLeg,
        UpperBody     = Arms     | Spine,
        All           = Arms     | Legs | Spine,
    }
    // Oneshot requests
    private static readonly StringName OneshotLeftArm  = "parameters/LeftArmOneshot";
    private static readonly StringName OneshotRightArm = "parameters/RightArmOneshot";
    private static readonly StringName OneshotLeftLeg  = "parameters/LeftLegOneshot";
    private static readonly StringName OneshotRightLeg = "parameters/RightLegOneshot";
    private static readonly StringName OneshotSpine    = "parameters/SpineOneshot";
    
    // Bundles
    private readonly AnimationBundle[] _oneshotBundle = new AnimationBundle[5];

    // Animation nodes
    private AnimationNodeAnimation _animationNodeLeftArm  = null!;
    private AnimationNodeAnimation _animationNodeLeftLeg  = null!;
    private AnimationNodeAnimation _animationNodeRightArm = null!;
    private AnimationNodeAnimation _animationNodeRightLeg = null!;
    private AnimationNodeAnimation _animationNodeSpine    = null!;
    private Character3D            _character             = null!;

    // Root
    private AnimationNodeBlendTree _root = null!;

    private AnimationNodeAnimation             _wholeBodyAnimationNode = null!;
    public override void _Ready() {
        base._Ready();
        _character = GetParent().GetParent<Character3D>();
        _root = (AnimationNodeBlendTree)TreeRoot;
        _animationNodeLeftArm = (AnimationNodeAnimation)_root.GetNode("LeftArmAnim");
        _animationNodeRightArm = (AnimationNodeAnimation)_root.GetNode("RightArmAnim");
        _animationNodeLeftLeg = (AnimationNodeAnimation)_root.GetNode("LeftLegAnim");
        _animationNodeRightLeg = (AnimationNodeAnimation)_root.GetNode("RightLegAnim");
        _animationNodeSpine = (AnimationNodeAnimation)_root.GetNode("SpineAnim");

        _oneshotBundle[0] = AnimationBundle.From(LeftArm,  _animationNodeLeftArm,  OneshotLeftArm);
        _oneshotBundle[1] = AnimationBundle.From(RightArm, _animationNodeRightArm, OneshotRightArm);
        _oneshotBundle[2] = AnimationBundle.From(LeftLeg,  _animationNodeLeftLeg,  OneshotLeftLeg);
        _oneshotBundle[3] = AnimationBundle.From(RightLeg, _animationNodeRightLeg, OneshotRightLeg);
        _oneshotBundle[4] = AnimationBundle.From(Spine,    _animationNodeSpine,    OneshotSpine);
    }
    public void PlayAnimation(
        StringName animation,
        LimbName mask,
        AnimationPriority iKOverridePriority
    ) {
        foreach (var bundle in _oneshotBundle) {
            if (!mask.HasFlag(bundle.Mask)) {
                continue;
            }

            Set(bundle.OneshotRequest, (int)AnimationNodeOneShot.OneShotRequest.Abort);
            bundle.AnimationNode.Animation = animation;
            
            // CAUSES ERROR
            Set(bundle.OneshotRequest, (int)AnimationNodeOneShot.OneShotRequest.Fire); // <--- THIS CAUSES A BAD SIGNAL INVOCATION
        }
    }
    private record struct AnimationBundle(
        LimbName Mask,
        AnimationNodeAnimation AnimationNode,
        StringName OneshotRequest
    ) {
        public static AnimationBundle From(LimbName mask, AnimationNodeAnimation node, StringName oneShotNode) {
            return new AnimationBundle(mask, node, $"{oneShotNode}/request");
        }
    }
}
```

If you need a repro project, I can do it but itll take some time to unpick this really specific type into an MRP.

Also, I tried my project with 4.7.dev2 and everything is fine, so it appears this is not a 4.7+ issue generally
